# ARKAVATHI Header Branding Patch
# Purpose:
#   1) Restore/show the supplied CNNL logo in the sidebar/header branding area.
#   2) Add Dr. K. Jaiprakash after the Water Resources Minister in the project header.
#   3) Preserve existing backend, routing, auth, permissions, GIS, workflow, database and page logic.
# Run this script from the ARKAVTHI_80PERCENT project root.

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$Root = (Get-Location).Path
$HeaderPath = Join-Path $Root 'frontend\src\components\AuthenticatedHeader.tsx'
$SidebarPath = Join-Path $Root 'frontend\src\components\Sidebar.tsx'
$BrandingDir = Join-Path $Root 'frontend\public\branding'
$CnnlPath = Join-Path $BrandingDir 'cnnl-logo.png'
$DrPath = Join-Path $BrandingDir 'dr-k-jaiprakash.png'

if (-not (Test-Path $HeaderPath)) { throw "AuthenticatedHeader.tsx not found: $HeaderPath" }
if (-not (Test-Path $SidebarPath)) { throw "Sidebar.tsx not found: $SidebarPath" }
if (-not (Test-Path $BrandingDir)) { New-Item -ItemType Directory -Force -Path $BrandingDir | Out-Null }

$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$BackupDir = Join-Path $Root "patch_backups\header_branding_$stamp"
New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

function Backup-IfExists([string]$Path, [string]$Name) {
    if (Test-Path $Path) { Copy-Item -Force $Path (Join-Path $BackupDir $Name) }
}

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $utf8)
}

Backup-IfExists $HeaderPath 'AuthenticatedHeader.tsx'
Backup-IfExists $SidebarPath 'Sidebar.tsx'
Backup-IfExists $CnnlPath 'cnnl-logo.png'
Backup-IfExists $DrPath 'dr-k-jaiprakash.png'

$CnnlBase64 = ''
$DrBase64 = ''

try {
    # ---------------------------------------------------------------------
    # Assets: write the exact user-supplied CNNL logo and Dr. Jaiprakash portrait.
    # ---------------------------------------------------------------------
    [System.IO.File]::WriteAllBytes($CnnlPath, [Convert]::FromBase64String($CnnlBase64))
    [System.IO.File]::WriteAllBytes($DrPath, [Convert]::FromBase64String($DrBase64))

    # ---------------------------------------------------------------------
    # Sidebar: canonical CNNL asset path + slightly larger visible logo.
    # ---------------------------------------------------------------------
    $sidebar = [System.IO.File]::ReadAllText($SidebarPath)
    $sidebar = $sidebar.Replace('/branding/cnnl-logo.webp', '/branding/cnnl-logo.png')
    $sidebar = [regex]::Replace(
        $sidebar,
        '(<img\s+src="/branding/cnnl-logo\.png"\s+alt="CNNL logo"\s+className=")h-10 w-10 object-contain("\s*/>)',
        '${1}h-11 w-11 object-contain${2}',
        1
    )
    Write-Utf8NoBom $SidebarPath $sidebar

    # ---------------------------------------------------------------------
    # Header: add a dedicated Dr. K. Jaiprakash block without changing the
    # existing CM / Water Resources Minister component implementation.
    # ---------------------------------------------------------------------
    $header = [System.IO.File]::ReadAllText($HeaderPath)

    if ($header -notmatch 'function\s+JaiprakashLeadershipBlock\s*\(') {
        $jaiprakashBlock = @'
function JaiprakashLeadershipBlock() {
  return (
    <div className="flex min-h-[78px] w-[360px] shrink-0 items-center px-4">
      <div className="grid h-14 w-14 shrink-0 place-items-center overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-white/70">
        <img
          src="/branding/dr-k-jaiprakash.png"
          alt="Dr. K. Jaiprakash"
          className="h-full w-full object-cover object-top"
        />
      </div>
      <div className="ml-3 min-w-0 flex-1">
        <div className="text-[11px] font-black leading-[14px] text-white">Dr. K. Jaiprakash</div>
        <div className="mt-0.5 text-[8.5px] font-semibold leading-[11px] text-blue-100">
          Former Secretary, Government of Karnataka and Chairman, Committee for Studies on Arkavathi River Basin
        </div>
      </div>
    </div>
  )
}

'@
        $dividerMarker = 'function HeaderDivider() {'
        $dividerIndex = $header.IndexOf($dividerMarker)
        if ($dividerIndex -lt 0) { throw 'Could not find HeaderDivider() anchor. No source changes were kept.' }
        $header = $header.Insert($dividerIndex, $jaiprakashBlock)
    }

    # Prevent the extra person block from creating horizontal overflow on narrower screens.
    $header = $header.Replace(
        'className="mx-auto flex max-w-[1700px] flex-wrap items-center gap-y-2 xl:flex-nowrap"',
        'className="mx-auto flex max-w-[1700px] flex-wrap items-center gap-y-2 min-[1800px]:flex-nowrap"'
    )
    $header = $header.Replace(
        'className="ml-auto flex flex-wrap items-center xl:flex-nowrap"',
        'className="ml-auto flex flex-wrap items-center min-[1800px]:flex-nowrap"'
    )

    if ($header -notmatch '<JaiprakashLeadershipBlock\s*/>') {
        $pattern = '(?<water><LeadershipBlock\s*\r?\n\s*portrait="/branding/water-resources-minister\.png"\s*\r?\n\s*title="Hon''ble Minister for Water Resources"\s*\r?\n\s*name="Shri Cheluvaraya Swami"\s*\r?\n\s*/>\s*\r?\n\s*<HeaderDivider\s*/>)'
        if (-not [regex]::IsMatch($header, $pattern)) {
            throw 'Could not find the Water Resources Minister header anchor. No source changes were kept.'
        }
        $replacement = '${water}' + "`r`n            <JaiprakashLeadershipBlock />`r`n            <HeaderDivider />"
        $header = [regex]::Replace($header, $pattern, $replacement, 1)
    }

    Write-Utf8NoBom $HeaderPath $header

    # ---------------------------------------------------------------------
    # Safety verification: make sure the intended source markers/assets exist.
    # ---------------------------------------------------------------------
    $checkHeader = [System.IO.File]::ReadAllText($HeaderPath)
    $checkSidebar = [System.IO.File]::ReadAllText($SidebarPath)

    if ($checkHeader -notmatch 'Dr\. K\. Jaiprakash') { throw 'Header validation failed: Dr. K. Jaiprakash text is missing.' }
    if ($checkHeader -notmatch '/branding/dr-k-jaiprakash\.png') { throw 'Header validation failed: Dr. K. Jaiprakash asset path is missing.' }
    if ($checkSidebar -notmatch '/branding/cnnl-logo\.png') { throw 'Sidebar validation failed: CNNL asset path is missing.' }
    if (-not (Test-Path $CnnlPath)) { throw 'CNNL asset write failed.' }
    if (-not (Test-Path $DrPath)) { throw 'Dr. K. Jaiprakash asset write failed.' }

    # TypeScript compile validation when Node + local TypeScript are available.
    $node = $null
    $nodeCommand = Get-Command node -ErrorAction SilentlyContinue
    if ($nodeCommand) {
        $node = $nodeCommand.Source
    } elseif (Test-Path 'C:\Program Files\nodejs\node.exe') {
        $node = 'C:\Program Files\nodejs\node.exe'
    }

    $tsc = Join-Path $Root 'frontend\node_modules\typescript\bin\tsc'
    if ($node -and (Test-Path $tsc)) {
        Write-Host 'Running TypeScript validation...' -ForegroundColor Cyan
        Push-Location (Join-Path $Root 'frontend')
        try {
            & $node 'node_modules\typescript\bin\tsc' --noEmit
            if ($LASTEXITCODE -ne 0) { throw "TypeScript validation failed with exit code $LASTEXITCODE" }
        } finally {
            Pop-Location
        }
    } else {
        Write-Warning 'Node/local TypeScript compiler was not available, so automatic tsc validation was skipped.'
    }

    Write-Host ''
    Write-Host 'PATCH APPLIED SUCCESSFULLY' -ForegroundColor Green
    Write-Host "Backup: $BackupDir"
    Write-Host 'Changed only:'
    Write-Host '  frontend\src\components\AuthenticatedHeader.tsx'
    Write-Host '  frontend\src\components\Sidebar.tsx'
    Write-Host '  frontend\public\branding\cnnl-logo.png'
    Write-Host '  frontend\public\branding\dr-k-jaiprakash.png'
    Write-Host ''
    Write-Host 'If Vite is already running, open http://localhost:5173 and press Ctrl+Shift+R.'
    Write-Host 'For a production build, run: cd frontend; npm.cmd run build'
}
catch {
    Write-Host ''
    Write-Host 'PATCH FAILED - restoring backed-up source files.' -ForegroundColor Red

    if (Test-Path (Join-Path $BackupDir 'AuthenticatedHeader.tsx')) {
        Copy-Item -Force (Join-Path $BackupDir 'AuthenticatedHeader.tsx') $HeaderPath
    }
    if (Test-Path (Join-Path $BackupDir 'Sidebar.tsx')) {
        Copy-Item -Force (Join-Path $BackupDir 'Sidebar.tsx') $SidebarPath
    }
    if (Test-Path (Join-Path $BackupDir 'cnnl-logo.png')) {
        Copy-Item -Force (Join-Path $BackupDir 'cnnl-logo.png') $CnnlPath
    }
    if (Test-Path (Join-Path $BackupDir 'dr-k-jaiprakash.png')) {
        Copy-Item -Force (Join-Path $BackupDir 'dr-k-jaiprakash.png') $DrPath
    } elseif (Test-Path $DrPath) {
        Remove-Item -Force $DrPath
    }

    throw
}
